def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    # result[x] will store the total occupied days for value x
    # Using 0-indexed for storage where index i corresponds to x = i+1
    result = [0] * n

    # For each x from 1 to n
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)  # 1-indexed, pad for convenience
        total_occupied = 0

        for l, r in offers:
            # Condition 1: Check if offer length is at least x
            if r - l + 1 < x:
                continue

            # Condition 2: Check if any day in [l, r] is already occupied
            occupied_in_range = False
            for day in range(l, r + 1):
                if occupied[day]:
                    occupied_in_range = True
                    break

            if not occupied_in_range:
                # Accept the offer
                for day in range(l, r + 1):
                    occupied[day] = True
                    total_occupied += 1

        result[x - 1] = total_occupied

    # Convert to string format
    return '\n'.join(str(result[i]) for i in range(n))

