            # Up
            if r > 0:
                adj[u].append((r - 1) * m + c)
            # Down
            if r < n - 1:
                adj[u].append((r + 1) * m + c)
            # Left
            if c > 0:
                adj[u].append(r * m + (c - 1))
            # Right
            if c < m - 1:
                adj[u].append(r * m + (c + 1))

    matchR = [-1] * total_cells

    def dfs(u, visited):
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if matchR[v] < 0 or dfs(matchR[v], visited):
                    matchR[v] = u
                    return True
        return False

    matching_size = 0
    for i in range(total_cells):
        visited = [False] * total_cells
        if dfs(i, visited):
            matching_size += 1

