import sys

def solution(input_str):
    MOD = 10**9 + 7

    # Parse the input - could have newlines between rows
    data = input_str.strip().split()
    n = int(data[0])
    a = [int(x) for x in data[1:]]

    if n == 1:
        return str(a[0] % MOD)

    # Current row starts as input array
    current = a[:]

    # First operation is addition, then alternate
    next_op_is_add = True

    while len(current) > 1:
        next_row = [0] * (len(current) - 1)
        for i in range(len(current) - 1):
            if next_op_is_add:
                val = (current[i] + current[i+1]) % MOD
            else:
                val = (current[i] - current[i+1]) % MOD
                # Handle negative result
                val = (val + MOD) % MOD
            next_row[i] = val
        current = next_row
        # Toggle operation direction for next row
        next_op_is_add = not next_op_is_add

    return str(current[0])

