                # Type 1: Apply ceil(val + x) up to y times
                # ceil(val + a * x) = ceil((val * 100000 + a * x_prime) / 100000)
                for a in range(y + 1):
                    num = val * 100000 + a * x_prime
                    new_val = ceil(num / 100000.0)
                    if new_val <= m:
                        next_vals.add(new_val)
            else:
                # Type 2: Apply ceil(val * x) iteratively up to y times
                new_val = val
                for a in range(y + 1):
                    if new_val > m:
                        break
                    if a > 0:
                        new_val = ceil(new_val * (x_prime / 100000.0))
                        if new_val > m:
                            break
                    next_vals.add(min(new_val, m))

