            dx, dy, char = directions[i][0], directions[i][1], directions[i][2]
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in reachable:
                if is_valid_move(x, y, i):
