        for i in range(2 * n):
            c1 = (i % (2 * n)) + 1
            c2 = ((i + 1) % (2 * n)) + 1
            c3 = ((i + 2) % (2 * n)) + 1
            if food[c1] == food[c2] == food[c3]:
                return False
        return True

    def assign_pair(boy, girl):
        if food[boy] != 0 and food[girl] != 0:
            return food[boy] != food[girl]
        if food[boy] != 0:
            food[girl] = 3 - food[boy]
            return check_assignment()
        if food[girl] != 0:
            food[boy] = 3 - food[girl]
            return check_assignment()
        food[boy] = 1
        food[girl] = 2
        return check_assignment()

    for pos1, pos2, _ in pairs:
        if not assign_pair(pos1, pos2):
            food[boy_positions[pos1]] = 0
            food[girl_positions[pos2]] = 0
            return False

    result_lines = []
    for a, b, idx in pairs:
        result_lines.append(f"{food[a]} {food[b]}")

    return '\n'.join(result_lines)

