def solution(s):
    s = s.strip('\n')
    n = len(s)

    if n == 0:
        return "0\n"

    # If entire string is a palindrome, that's the best
    if s == s[::-1]:
        return f"1\n1 {n}\n"

    best_total = -1
    best_cases = None

    for plen in range(1, (n + 1) // 2 + 1):
        if 2 * plen >= n:
            break

        prefix = s[:plen]
        prefix_rev = prefix[::-1]

        # Find where prefix_rev appears in s
        for start in range(plen, n - plen + 1):
            if s[start:start+plen] == prefix_rev:
                mid_len = start - plen

                if mid_len > 0 and mid_len % 2 == 1:
                    total = plen * 2 + mid_len
                    if total > best_total:
                        best_total = total
                        best_cases = {
                            'count': 3,
                            'parts': [
                                (plen + 1, plen * 2),
                                (plen + 1, mid_len),
                                (start + 1, plen)
                            ]
                        }
                        break

    if best_cases is not None and best_total > 0:
        output_lines = [str(best_cases['count'])]
        for pos, length in best_cases['parts']:
            output_lines.append(f"{pos} {length}")
        return "\n".join(output_lines) + "\n"

    # Try to find any odd-length palindrome substring
    best_pal_len = 0
    best_pal_pos = 0
    for start in range(n):
        for end in range(start, n):
            substr = s[start:end+1]
            if substr == substr[::-1] and (end - start + 1) % 2 == 1:
                if (end - start + 1) > best_pal_len:
                    best_pal_len = end - start + 1
                    best_pal_pos = start + 1

    if best_pal_len > 0:
        return f"1\n{best_pal_pos} {best_pal_len}\n"

    return "0\n"


