def solution(s):
    s = s.strip('\n')
    n = len(s)
    if n == 0:
        return "0\n"

    if s == s[::-1]:
        return f"1\n1 {n}\n"

    best_total = -1
    best_pref_len = best_mid_len = best_suff_pos = best_suff_len = 0

    for plen in range(1, (n + 1) // 2 + 1):
        if 2 * plen >= n:
            break
        prefix = s[:plen]
        prefix_rev = prefix[::-1]
        for i in range(plen, n - plen + 1):
            if s[i:i+plen] == prefix_rev:
                mid_len = i - plen
                if mid_len > 0 and mid_len % 2 == 1:
                    total = plen * 2 + mid_len
                    if total > best_total:
                        best_total = total
                        best_pref_len = plen
                        best_mid_len = mid_len
                        best_suff_pos = i + 1
                        best_suff_len = plen

    if best_total > 0:
        return f"3\n1 {best_pref_len * 2}\n{best_pref_len + 1} {best_mid_len}\n{best_suff_pos} {best_suff_len}\n"

    best_pal = best_start = 0
    for i in range(n):
        for j in range(i, n):
            if s[i:j+1] == s[i:j+1][::-1] and (j - i + 1) % 2 == 1:
                if j - i + 1 > best_pal:
                    best_pal = j - i + 1
                    best_start = i + 1
    if best_pal > 0:
        return f"1\n{best_start} {best_pal}\n"

    return "0\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    m, n, p = len(s1), len(s2), len(virus)

    if p == 0:
        return "0"

    # KMP prefix function for virus
    pi = [0] * p
    j = 0
    for i in range(1, p):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # KMP transition: what's the new KMP state after seeing character c?
    def kmp_next(k, c):
        while k > 0 and c != virus[k]:
            k = pi[k-1]
        if c == virus[k]:
            k += 1
        return k

    # dp[i][j][k] = max length of LCS using s1[:i], s2[:j] ending with virus state k
    dp = [[[-1] * p for _ in range(n + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 0

    # Parent for reconstruction: (type, prev_i, prev_j, prev_k)
    par = [[[None] * p for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(p):
                if dp[i][j][k] == -1:
                    continue

                current_len = dp[i][j][k]

                # Skip s1[i]
                if i < m:
                    if dp[i+1][j][k] < current_len:
                        dp[i+1][j][k] = current_len
                        par[i+1][j][k] = ('S1', i, j, k)

                # Skip s2[j]
                if j < n:
                    if dp[i][j+1][k] < current_len:
                        dp[i][j+1][k] = current_len
                        par[i][j+1][k] = ('S2', i, j, k)

                # Match
                if i < m and j < n and s1[i] == s2[j]:
                    prev_k = k
                    new_k = kmp_next(prev_k, s1[i])
                    if new_k < p:  # Don't complete virus as substring
                        if dp[i+1][j+1][new_k] < current_len + 1:
                            dp[i+1][j+1][new_k] = current_len + 1
                            par[i+1][j+1][new_k] = ('MATCH', i, j, prev_k)

    # Find best result
    best_len = 0
    best_k = 0
    for k in range(p):
        if dp[m][n][k] > best_len:
            best_len = dp[m][n][k]
            best_k = k

    if best_len == 0:
        return "0"

    # Reconstruct the solution
    i, j, k = m, n, best_k
    res = []

    while True:
        p_state = par[i][j][k]
        if p_state is None:
            break

        op, pi, pj, pk = p_state

        if op == 'MATCH':
            res.append(s1[pi])
            i, j, k = pi - 1, pj - 1, pk
        elif op == 'S1':
            i, j, k = pi - 1, j, k
        else:  # S2
            i, j, k = i, pj - 1, pk

    return ''.join(reversed(res))

def solution(input_data: str) -> str:
    import sys

    input_data = input_data.strip().split('\n')
    idx = 0
    t = int(input_data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(input_data[idx])
        idx += 1
        p = list(map(int, input_data[idx].split()))
        idx += 1

        # Try to build a valid configuration using greedy approach
        # lanterns are 1-indexed in problem, 0-indexed in our code
        directions = [''] * n  # 'L' or 'R'
        satisfied = [False] * n

        # We'll try a greedy approach: process from left to right
        # For each lantern, if not yet satisfied, we'll try to satisfy it
        # and also ensure it can satisfy others if possible

        # First pass: try to satisfy lanterns going left
        for i in range(n - 1, -1, -1):
            if not satisfied[i]:
                # Try to satisfy lantern i by making some lantern to its right point left
                # or some lantern to its left point right
                found = False

                # Check if we can be illuminated from the right
                if not found:
                    for j in range(i + 1, min(i + p[i] + 1, n)):
                        if not satisfied[j] and directions[j] == '':
                            # j can illuminate i if j points left and p[j] >= (j - i)
                            if j - i <= p[j]:
                                directions[j] = 'L'
                                satisfied[i] = True
                                satisfied[j] = False  # j is being used to illuminate i
                                found = True
                                break

                if not found:
                    # Try to be illuminated from the left
                    for j in range(max(0, i - p[i]), i):
                        if not satisfied[j] and directions[j] == '':
                            if i - j <= p[j]:
                                directions[j] = 'R'
                                satisfied[i] = True
                                found = True
                                break

